<script setup>
import { computed, onMounted, ref, watch } from 'vue'
const key='zoocare_animals', title='Animals', noun='animal'
const items=ref([]), search=ref(''), showForm=ref(false), editing=ref(null), message=ref('')
const empty=()=>({name:'',species:'',habitat:'',age:1,status:'Healthy'}), form=ref(empty())
onMounted(()=>items.value=JSON.parse(localStorage.getItem(key)||'[]'))
watch(items,v=>localStorage.setItem(key,JSON.stringify(v)),{deep:true})
const filtered=computed(()=>items.value.filter(a=>[a.name,a.species,a.habitat,a.status].join(' ').toLowerCase().includes(search.value.toLowerCase())))
function openAdd(){editing.value=null;form.value=empty();showForm.value=true;message.value=''}
function edit(a){editing.value=a.id;form.value={...a};showForm.value=true;message.value=''}
function save(){if(!form.value.name.trim()||!form.value.species.trim()){message.value='Animal name and species are required.';return}if(editing.value!==null){const i=items.value.findIndex(a=>a.id===editing.value);items.value[i]={...form.value,name:form.value.name.trim()}}else items.value.push({...form.value,id:Date.now(),name:form.value.name.trim()});showForm.value=false;message.value='Animal saved successfully.'}
function remove(id){if(confirm('Delete this animal?'))items.value=items.value.filter(a=>a.id!==id)}
</script>
<template><div class="page-title-row"><div><p class="eyebrow">ANIMAL DIRECTORY</p><h1>Animals</h1><p class="muted">Register animals and maintain their basic information.</p></div><button class="btn btn-primary" @click="openAdd">+ Add animal</button></div><div class="toolbar"><input v-model="search" class="search-input" placeholder="Search name, species, habitat, or status..."><span class="result-count">{{ filtered.length }} animals</span></div><div v-if="showForm" class="form-panel"><div class="panel-heading"><h2>{{ editing!==null?'Edit animal':'Add animal' }}</h2><button class="icon-button" @click="showForm=false">Close</button></div><form @submit.prevent="save" class="form-grid"><label>Animal name<input v-model="form.name" placeholder="e.g. Kiko" required></label><label>Species<input v-model="form.species" placeholder="e.g. Philippine eagle" required></label><label>Habitat<input v-model="form.habitat" placeholder="e.g. Aviary"></label><label>Age (years)<input v-model.number="form.age" type="number" min="0" required></label><label>Health status<select v-model="form.status"><option>Healthy</option><option>Under observation</option><option>Under treatment</option></select></label><div class="form-actions"><button class="btn btn-primary" type="submit">Save animal</button><span class="form-message">{{ message }}</span></div></form></div><div class="table-card"><table><thead><tr><th>NAME</th><th>SPECIES</th><th>HABITAT</th><th>AGE</th><th>HEALTH STATUS</th><th>ACTIONS</th></tr></thead><tbody><tr v-for="a in filtered" :key="a.id"><td><strong>{{ a.name }}</strong></td><td>{{ a.species }}</td><td>{{ a.habitat||'—' }}</td><td>{{ a.age }}</td><td><span class="pill" :class="a.status==='Under treatment'?'occupied':''">{{ a.status }}</span></td><td><div class="actions"><button class="action-link" @click="edit(a)">Edit</button><button class="action-link danger" @click="remove(a.id)">Delete</button></div></td></tr><tr v-if="!filtered.length"><td colspan="6" class="empty-state">No animals found. Add an animal to get started.</td></tr></tbody></table></div></template>
